import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { SheetBody } from '../../slots/defs/sheet';
import { claimsKey, useClaims } from './claims';
import { clearSelected, useSelectedClaims } from './selection';

type BulkOpenResult = { opened: number; refused: number };

/** The button that opens every selected claim together. The server opens each that can be opened, in list
 *  order, and leaves the rest as they are; the bar then shows how many were opened and how many refused. */
function BulkOpen({ sheetId, user }: { sheetId: string; user: string }) {
  const queryClient = useQueryClient();
  const claims = useClaims(sheetId).data ?? [];
  const chosen = useSelectedClaims(sheetId);
  const ids = claims.filter((c) => chosen.has(c.id)).map((c) => c.id);
  const [result, setResult] = useState<BulkOpenResult | null>(null);
  const [error, setError] = useState('');
  const once = useSubmitOnce();

  const open = useMutation({
    mutationFn: (claimIds: number[]) =>
      postJson<BulkOpenResult>(`/api/sheets/${encodeURIComponent(sheetId)}/bulk-open`, { user, claimIds }),
    onSuccess: async (r) => {
      clearSelected(sheetId);
      setResult(r);
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
    onError: (e) => setError(e instanceof HttpError && e.body ? e.body : 'Could not open the selected claims.'),
    onSettled: once.done,
  });

  return (
    <p>
      <button
        type="button"
        data-testid="bulk-open"
        disabled={open.isPending}
        onClick={() => {
          setError('');
          setResult(null);
          if (ids.length === 0) {
            setError('Select the claims to open.');
            return;
          }
          if (!once.start()) return;
          open.mutate(ids);
        }}
      >
        Open selected
      </button>
      {result && (
        <>
          {' '}Opened <span data-testid="bulk-opened">{result.opened}</span>, refused{' '}
          <span data-testid="bulk-refused">{result.refused}</span>
        </>
      )}
      {error && (
        <span data-testid="bulk-open-error" role="alert">
          {' '}{error}
        </span>
      )}
    </p>
  );
}

export const contribution = SheetBody.fill({ order: 12, Component: BulkOpen });
import { useSyncExternalStore } from 'react';

// The claims selected for a bulk action, per sheet. Kept outside React state because the checkboxes (on
// each claim's row) and the bulk buttons (on the sheet) are filled into different slots.
const selected = new Map<string, Set<number>>();
const listeners = new Set<() => void>();
const NONE: Set<number> = new Set();

function notify() {
  for (const l of listeners) l();
}

function subscribe(l: () => void) {
  listeners.add(l);
  return () => listeners.delete(l);
}

/** Select or clear one claim on the sheet. */
export function setSelected(sheetId: string, claimId: number, on: boolean) {
  const next = new Set(selected.get(sheetId) ?? NONE);
  if (on) next.add(claimId);
  else next.delete(claimId);
  selected.set(sheetId, next);
  notify();
}

/** Clear the sheet's selection. */
export function clearSelected(sheetId: string) {
  selected.delete(sheetId);
  notify();
}

/** The ids of the claims selected on the sheet. */
export function useSelectedClaims(sheetId: string): Set<number> {
  return useSyncExternalStore(subscribe, () => selected.get(sheetId) ?? NONE);
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asString, useSearchParam } from '../../url/useSearchParam';
import { heldOn } from '../people/people';
import type { Person } from '../people/people';

/** Where a claim is in its life: DRAFT, then OPEN, then SETTLED; a clerk's settle above the clerk limit leaves it
 *  PENDING until a steward approves (SETTLED) or rejects (OPEN) it; a DRAFT, OPEN or PENDING claim may be VOID. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

/** Every claim status, in life order: the statuses claims are counted by, each shown even when no claim has it. */
export const STATUSES: readonly ClaimStatus[] = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'];

/** A person's claim: the amount with two decimals, the date (yyyy-mm-dd), a note (may be empty), its status,
 *  its number (sheet-wide digits, or <period name>-<n> / X-<n> when numbered within its period; null while a draft; a voided claim keeps the one it had) and, the due fixed when it was settled
 *  (null when not settled, or its grade had no rate then: its due follows the rates), and who opened it
 *  (null while a draft), whether its person's last statement bound it (it counted then) and the figure it bound
 *  it to (null when not bound, or n/a then: its due stays live), and for a correction (a negative amount) the
 *  number of the SETTLED claim of the same person it corrects (null otherwise), and its due-by (yyyy-mm-dd), fixed
 *  when it was created from the terms of its person's grade in force on its date (else the sheet's terms), and its
 *  status log: one line per status it has had, oldest first, as <STATUS> by <user> on <date> due=<due>. */
export type Claim = { id: number; personId: number; amount: string; date: string; note: string; status: ClaimStatus;
  number: string | null; settledDue: string | null; openedBy: string | null; stated: boolean;
  statedDue: string | null; corrects: string | null; dueBy: string; log: string[] };

/** Whether a claim counts toward claimed, due-total and every total: only OPEN, PENDING and SETTLED ones do. */
export function counts(c: Claim): boolean {
  return c.status === 'OPEN' || c.status === 'PENDING' || c.status === 'SETTLED';
}

/** Whether a claim is still to be settled: OPEN or PENDING (it goes overdue). */
export function unsettled(c: Claim): boolean {
  return c.status === 'OPEN' || c.status === 'PENDING';
}

/** The claims that count in the live totals among these: those that count, except an OPEN claim dated within a hold
 *  of its person (among the people given) and not bound by a statement; their other claims still count. */
export function live(claims: Claim[], people: Person[]): Claim[] {
  const byId = new Map(people.map((p) => [p.id, p]));
  return claims.filter((c) => counts(c) && !(c.status === 'OPEN' && !c.stated && heldOn(byId.get(c.personId), c.date)));
}

/** A claim's due-by (yyyy-mm-dd), as fixed when it was created. */
export function dueBy(claim: Claim): string {
  return claim.dueBy;
}

/** Whether a claim is overdue: it is OPEN or PENDING and its due-by is before the sheet's today. */
export function overdue(claim: Claim, today: string): boolean {
  return unsettled(claim) && today !== '' && dueBy(claim) < today;
}

export const claimsKey = (sheetId: string) => ['sheet', sheetId, 'claims'] as const;

/** Every claim on the sheet, newest first. */
export function useClaims(sheetId: string) {
  return useQuery({
    queryKey: claimsKey(sheetId),
    queryFn: () => getJson<Claim[]>(`/api/sheets/${encodeURIComponent(sheetId)}/claims`),
  });
}

/** The id of the claim whose editor is open ('' when each person's claim form adds a new claim). */
export function useEditingClaim() {
  return useSearchParam('editClaim', asString);
}

/** The amounts of the claims that count (OPEN, PENDING and SETTLED) added up exactly (in cents) and shown
 *  with two decimals. */
export function sumAmounts(claims: Claim[]): string {
  const cents = claims.filter(counts).reduce((total, c) => total + Math.round(Number(c.amount) * 100), 0);
  const abs = Math.abs(cents);
  return `${cents < 0 ? '-' : ''}${Math.floor(abs / 100)}.${String(abs % 100).padStart(2, '0')}`;
}
package net.officefloor.hq.app.claim;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.Rollups;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Open each selected claim that can be opened, in list order (people in the order they were added, newest
 *  claim first within a person), giving each the sheet's next number. Each is opened as a single open would be,
 *  with its OPEN line in its status log, its CLAIM_OPENED line and then how the sheet's figures moved over it. A selected claim that cannot be
 *  opened (not on the sheet, not a DRAFT, or dated in a closed period) is left as it is and counted as refused. */
public class BulkOpenClaims {
    public void open(@PathVariable("sheetId") String sheetId, @Val BulkOpenInput input, ClaimRepository claims, ClaimLogRepository log,
            PersonRepository people, PeriodRepository periods, Rollups rollups, Audit audit,
            Out<BulkOpenResponse> result) {
        String sheet = sheetId.trim();
        periods.lockSheet(sheet);
        int opened = 0;
        for (Person person : people.list(sheet)) {
            List<Claim> theirs = claims.listForPerson(sheet, person.id()).stream()
                    .filter(c -> input.claimIds().contains(c.id())).toList();
            for (Claim claim : theirs) {
                if (claim.status().canBecome(ClaimStatus.OPEN) && periods.closedOn(sheet, claim.date()) == null) {
                    Rollup before = rollups.take(sheet);
                    String number = claims.nextNumber(sheet, claim.date());
                    claims.changeStatus(claim, ClaimStatus.OPEN, number, claim.settledDue(), input.user());
                    log.record(claim, input.user());
                    audit.record("CLAIM_OPENED sheet=" + sheet + " by=" + input.user() + " person=" + person.name()
                            + " amount=" + claim.amount().toPlainString() + " date=" + claim.date() + " number=" + number);
                    rollups.record(sheet, input.user(), before);
                    opened++;
                }
            }
        }
        result.set(new BulkOpenResponse(opened, input.claimIds().size() - opened));
    }
}
